-- Dire Maul (map 429): import the creature and gameobject spawns SkyFire lacks, from 4.3.4 (Dire Maul was re-levelled
-- by Cataclysm and 4.3.4 matches SkyFire's templates; 3.3.5 has the same spawn layout).
-- A 4.3.4 creature spawn is imported only if no SkyFire spawn of the same entry is within 15 yards (one-to-one, nearest pair first, so a
-- SkyFire spawn absorbs at most one 4.3.4 spawn),
-- so SkyFire's own spawns are kept. spawnMask 2 (normal 5-man). Reserved ids: creature guids 8302000 to 8302999, gameobject guids 910200 to 910299,
-- waypoint path id = creature guid * 10 (a path shared by several creatures takes the id of the first creature that uses it).
-- Safe to run twice: each block deletes its reserved id range first.

DELETE FROM `creature` WHERE `guid` BETWEEN 8302000 AND 8302999;

DELETE FROM `creature_addon` WHERE `guid` BETWEEN 8302000 AND 8302999;

DELETE FROM `waypoint_data` WHERE `id` BETWEEN 83020000 AND 83029999;
-- Patrols moved onto existing SkyFire spawns that have none (path id = SkyFire guid * 10).
DELETE FROM `waypoint_data` WHERE `id` IN (841580);

-- Existing SkyFire spawns that absorbed a patrolling 4.3.4 spawn and have no patrol of their own: give them the patrol.
UPDATE `creature_addon` SET `path_id` = 841580 WHERE `guid` = 84158 AND `path_id` = 0;
UPDATE `creature` SET `MovementType` = 2 WHERE `guid` = 84158 AND `map` = 429 AND `MovementType` <> 2;

DELETE FROM `creature_formations` WHERE `memberGUID` IN (8302015, 8302016, 8302017, 8302018, 8302019, 8302020, 8302021, 8302022, 8302023, 8302024, 8302025, 8302026, 8302027, 8302028, 8302029, 8302030, 8302031, 8302032, 8302033, 8302034);

DELETE FROM `gameobject` WHERE `guid` BETWEEN 910200 AND 910299;
